   378→/**
   379→ * Analyze recovery timeline from simulation history
   380→ * Detects decline/inflection/recovery phases, key events, and mechanisms
   381→ */
   382→function analyzeRecoveryTimeline(runResult: any, finalState: any): RunResult['recoveryTimeline'] {
   383→  const popHistory: Array<{ month: number; pop: number; qol: number }> = [];
   384→
   385→  // Extract population and QoL history
   386→  if (finalState.humanPopulationSystem && runResult.log && runResult.log.snapshots && Array.isArray(runResult.log.snapshots)) {
   387→    runResult.log.snapshots.forEach((snapshot: any, idx: number) => {
   388→      if (snapshot.humanPopulationSystem && snapshot.globalMetrics) {
   389→        popHistory.push({
   390→          month: snapshot.currentMonth || idx,
   391→          pop: snapshot.humanPopulationSystem.population || 8.0,
   392→          qol: snapshot.globalMetrics.qualityOfLife || 0.5
   393→        });
   394→      }
   395→    });
   396→  }
   397→
   398→  if (popHistory.length < 3) {
   399→    return undefined; // Not enough data
   400→  }
   401→
   402→  // Detect phases (decline, inflection, recovery)
   403→  const phases: RunResult['recoveryTimeline']['phases'] = [];
   404→  let currentPhase: 'decline' | 'inflection' | 'recovery' | 'stable' | 'collapse' = 'stable';
   405→  let phaseStartMonth = 0;
   406→  let phaseStartPop = popHistory[0].pop;
   407→  let phaseStartQoL = popHistory[0].qol;
   408→
   409→  for (let i = 1; i < popHistory.length; i++) {
   410→    const prev = popHistory[i - 1];
   411→    const curr = popHistory[i];
   412→    const popChange = (curr.pop - prev.pop) / prev.pop;
   413→    const qolChange = curr.qol - prev.qol;
   414→
   415→    // Detect phase transitions
   416→    let newPhase: typeof currentPhase | null = null;
   417→
   418→    if (popChange < -0.03) {
   419→      // Significant decline (>3% population loss)
   420→      if (currentPhase !== 'decline' && currentPhase !== 'collapse') {
   421→        newPhase = 'decline';
   422→      }
