'use client';

import { useEffect } from 'react';
import { useGameStore } from '@/lib/gameStore';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from '@/components/ui/collapsible';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';
import { 
  Play, 
  Pause, 
  FastForward, 
  Settings, 
  ChevronUp,
  Heart,
  Users,
  Shield,
  TrendingUp,
  Brain,
  Building,
  Zap
} from 'lucide-react';

// Individual tab components
import OverviewTab from './tabs/OverviewTab';
import AgentsTab from './tabs/AgentsTab';
import DynamicsTab from './tabs/DynamicsTab';
import TechnologyTab from './tabs/TechnologyTab';
import EconomyTab from './tabs/EconomyTab';
import ControlsTab from './tabs/ControlsTab';
import AnalysisTab from './tabs/AnalysisTab';
import ActionsSidebar from './ActionsSidebar';

// Metric card component
interface MetricCardProps {
  label: string;
  value: number;
  max: number;
  color: 'green' | 'blue' | 'red' | 'amber' | 'purple';
  icon: React.ReactNode;
}

const MetricCard: React.FC<MetricCardProps> = ({ label, value, max, color, icon }) => {
  const percentage = Math.max(0, Math.min(100, (value / max) * 100));

  const colorClasses = {
    green: 'text-green-600',
    blue: 'text-blue-600', 
    red: 'text-red-600',
    amber: 'text-amber-600',
    purple: 'text-purple-600'
  };

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2">
        <div className={colorClasses[color]}>{icon}</div>
        <span className="text-sm font-medium">{label}</span>
      </div>
      <div className="text-2xl font-bold">
        {percentage.toFixed(0)}%
      </div>
      <Progress value={percentage} className="h-2" />
    </div>
  );
};

export default function GameLayout() {
  const { 
    currentMonth,
    currentDay,
    speed, 
    gameStarted,
    globalMetrics,
    outcomeMetrics,
    eventLog,
    history,
    dispatch,
    startGame,
    pauseGame,
    resetGame,
    processMonthlyUpdate,
    processDailyUpdate,
    getCurrentDateString,
    getMonthProgress
  } = useGameStore();

  // Simulation loop - day-based timing
  useEffect(() => {
    if (speed === 'paused' || !gameStarted) return;

    const speedMap = {
      slow: 2000,    // 2 seconds per day (slow)
      normal: 1000,  // 1 second per day (immersive)
      fast: 500,     // 0.5 seconds per day (fast)

