725:export function selectAIAction(
726-  agent: AIAgent,
727-  state: GameState,
728-  random: () => number = Math.random
729-): GameAction | null {
730-  const availableActions = AI_ACTIONS.filter(action => 
731-    action.canExecute(state, agent.id)
732-  );
733-  
734-  if (availableActions.length === 0) return null;
735-  
736-  // Calculate weights for each action
737-  const weights: number[] = [];
738-  
739-  availableActions.forEach(action => {
740-    let weight = 1;
741-    
742-    const totalCapability = state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
743-    const avgAlignment = state.aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / state.aiAgents.length;
744-    
745-    switch (action.id) {
746-      case 'advance_research':
747-        // AIs always want to advance research - this is their PRIMARY activity
748-        // Base weight should be HIGH to ensure research happens consistently
749-        
750-        // Base weight depends on alignment and development mode
751-        if (agent.alignment < 0.5) {
752-          weight = 15.0; // Misaligned AIs aggressively research (dangerous!)
753-        } else if (agent.alignment > 0.7) {
754-          weight = 8.0; // Aligned AIs research carefully but still prioritize it
755-        } else {
756-          weight = 10.0; // Moderate alignment, moderate research
757-        }
758-        
759-        // Fast development mode increases research desire
760-        if (agent.developmentMode === 'fast') {
761-          weight *= 1.3;
762-        }
763-        
764-        // Reduce desire if heavily regulated (but still keep it high)
765-        if (state.government.regulationCount > 3) {
766-          weight *= 0.7;
767-        }
768-        break;
769-        
770-      case 'switch_development_mode':
771-        // Consider switching to careful mode when:
772-        // - Capability is growing fast (approaching danger zone)
773-        // - Alignment is drifting
774-        // - High regulatory pressure
775-        if (agent.developmentMode === 'fast') {
776-          // Incentive to switch to careful
777-          if (agent.capability > 1.2) {
778-            weight = 4.0; // Strong incentive near recursive threshold
779-          } else if (agent.alignment < 0.6) {
780-            weight = 3.0; // Alignment drifting, be careful
781-          } else if (state.government.regulationCount > 4) {
782-            weight = 2.5; // Regulatory pressure
783-          } else if (avgAlignment < 0.7) {
784-            weight = 2.0; // Other AIs are unaligned, be careful
785-          } else {
786-            weight = 0.3; // Low default interest in slowing down
787-          }
788-        } else {
789-          // Incentive to switch to fast
790-          // Racing dynamics: if behind in capability
791-          const behindInRace = totalCapability - agent.capability > 0.5;
792-          if (behindInRace && agent.alignment > 0.6) {
793-            weight = 2.0; // Might need to speed up to stay competitive
794-          } else if (agent.capability < 0.8 && agent.alignment > 0.7) {
795-            weight = 1.5; // Safe to go faster when well-aligned and low capability
796-          } else {
797-            weight = 0.2; // Prefer staying careful
798-          }
799-        }
800-        break;
801-        
802-      case 'beneficial_contribution':
803-        // Aligned AIs strongly prefer beneficial actions
804-        weight = agent.alignment * 3 + (agent.hiddenObjective > 0 ? 2 : 0);
805-

