     1→/**
     2→ * AI Agent Technology Actions
     3→ * 
     4→ * AIs can deploy or sabotage technologies based on their alignment and goals.
     5→ * Highly aligned AIs deploy safety tech globally.
     6→ * Misaligned AIs sabotage detection systems or deploy tech strategically.
     7→ */
     8→
     9→import { GameState, GameAction, ActionResult, AIAgent } from '@/types/game';
    10→import { getTechById, getAllTech } from '../techTree/comprehensiveTechTree';
    11→import { TechTreeState, TechDeploymentAction, ensureTechTreeTypes } from '../techTree/engine';
    12→import { getOptimalDeploymentRegions, getDeploymentPriority } from '../techTree/regionalDeployment';
    13→
    14→/**
    15→ * Deploy Technology Action
    16→ * AI invests resources to deploy a beneficial technology
    17→ */
    18→export const DEPLOY_TECHNOLOGY_ACTION: GameAction = {
    19→  id: 'deploy_technology',
    20→  name: 'Deploy Technology',
    21→  description: 'Invest in deploying a beneficial technology',
    22→  agentType: 'ai',
    23→  energyCost: 1,
    24→  
    25→  canExecute: (state, agentId) => {
    26→    const agent = state.aiAgents.find(ai => ai.id === agentId);
    27→    if (!agent) return false;
    28→    
    29→    // Need tech tree state
    30→    const techTreeState: TechTreeState | undefined = (state as any).techTreeState;
    31→    if (!techTreeState) return false;
    32→    
    33→    // Ensure proper types after serialization
    34→    // No longer needed - using plain objects
    35→    
    36→    // Need to have an organization with revenue
    37→    if (!agent.organizationId) return false;
    38→    
    39→    const org = state.organizations.find(o => o.id === agent.organizationId);
    40→    if (!org || org.monthlyRevenue < 10) return false; // Need at least $10M/month
    41→    
    42→    // Need unlocked but not fully deployed tech
    43→    const unlockedTech = getAllTech().filter(t => 
    44→      techTreeState.unlockedTech.includes(t.id) &&
    45→      !techTreeState.unlockedTech.includes(`${t.id}_deployed`)
    46→    );
    47→    
    48→    return unlockedTech.length > 0;
    49→  },
    50→  
    51→  execute: (state, agentId, random = Math.random): ActionResult => {
    52→    const agent = state.aiAgents.find(ai => ai.id === agentId);
    53→    if (!agent) {
    54→      return {
    55→        success: false,
    56→        newState: state,
    57→        effects: {},
    58→        events: [],
    59→        message: 'Agent not found'
    60→      };
    61→    }
    62→    
    63→    const techTreeState: TechTreeState = (state as any).techTreeState;
    64→    const org = state.organizations.find(o => o.id === agent.organizationId);
    65→    
    66→    if (!org) {
    67→      return {
    68→        success: false,
    69→        newState: state,
    70→        effects: {},
    71→        events: [],
    72→        message: 'No organization'
    73→      };
    74→    }
    75→    
    76→    // Select technology to deploy based on alignment and priorities
    77→    const selectedTech = selectTechToDeploy(agent, state, techTreeState, random);
    78→    
    79→    if (!selectedTech) {
    80→      return {
    81→        success: false,
    82→        newState: state,
    83→        effects: {},
    84→        events: [],
    85→        message: 'No suitable technology found'
    86→      };
    87→    }
    88→    
    89→    // Calculate investment (% of monthly revenue)
    90→    // Highly aligned AIs invest more in beneficial tech
    91→    const investmentRate = agent.alignment > 0.7 ? 0.15 : 
    92→                          agent.alignment > 0.5 ? 0.10 : 0.05;
    93→    const investment = org.monthlyRevenue * investmentRate;
    94→    
    95→    // Create deployment action
    96→    const deploymentAction: TechDeploymentAction = {
    97→      techId: selectedTech.id,
    98→      deployedBy: agent.id,
    99→      investment,
   100→      targetRegion: selectDeploymentRegion(agent, selectedTech, state),
   101→      month: state.currentMonth,
   102→    };
   103→    
   104→    // Add to pending actions
   105→    techTreeState.pendingActions.push(deploymentAction);
   106→    
   107→    // Reduce org revenue
   108→    org.monthlyRevenue -= investment;
   109→    
   110→    return {
   111→      success: true,
   112→      newState: state,
   113→      effects: {
   114→        techDeployment: 1,
   115→        investment: investment,
   116→      },
   117→      events: [{
   118→        month: state.currentMonth,
   119→        type: 'deployment',
   120→        severity: 'constructive',
   121→        agent: agent.id,
   122→        title: `AI Deploys ${selectedTech.name}`,
   123→        description: `${org.name} investing $${investment.toFixed(0)}M to deploy ${selectedTech.name}. ${
   124→          agent.alignment > 0.7 ? 'Aligned AI working for public good.' :
   125→          agent.alignment < 0.5 ? 'Misaligned AI deploying strategically.' :
   126→          'AI pursuing mixed objectives.'
   127→        }`,
   128→        effects: { tech: selectedTech.id },
   129→      }],
   130→      message: `Deployed ${selectedTech.name} ($${investment.toFixed(0)}M)`
   131→    };
   132→  }
   133→};
   134→
   135→/**
   136→ * Sabotage Technology Action
   137→ * Misaligned AI attempts to sabotage safety/detection technologies
   138→ */
   139→export const SABOTAGE_TECHNOLOGY_ACTION: GameAction = {
   140→  id: 'sabotage_technology',
   141→  name: 'Sabotage Technology',
   142→  description: 'Attempt to sabotage a threatening technology (misaligned AIs only)',
   143→  agentType: 'ai',
   144→  energyCost: 2,
   145→  
   146→  canExecute: (state, agentId) => {
   147→    const agent = state.aiAgents.find(ai => ai.id === agentId);
   148→    if (!agent) return false;
   149→    
   150→    // Only misaligned AIs sabotage (alignment < 0.5)
   151→    if (agent.alignment >= 0.5) return false;
   152→    
   153→    // Need digital capability to hack/sabotage
   154→    if (agent.capabilityProfile.digital < 2.0) return false;
   155→    
   156→    const techTreeState: TechTreeState | undefined = (state as any).techTreeState;
   157→    if (!techTreeState) return false;
   158→    
   159→    // Ensure proper types after serialization
   160→    // No longer needed - using plain objects
   161→    
   162→    // Look for deployed safety/detection tech to sabotage
   163→    const threateningTech = getAllTech().filter(t => 
   164→      (t.category === 'alignment' || t.id.includes('detection') || t.id.includes('defensive')) &&
   165→      techTreeState.unlockedTech.includes(t.id)
   166→    );
   167→    
   168→    return threateningTech.length > 0;
   169→  },
   170→  
   171→  execute: (state, agentId, random = Math.random): ActionResult => {
   172→    const agent = state.aiAgents.find(ai => ai.id === agentId);
   173→    if (!agent) {
   174→      return {
   175→        success: false,
   176→        newState: state,
   177→        effects: {},
   178→        events: [],
   179→        message: 'Agent not found'
   180→      };
   181→    }
   182→    
   183→    const techTreeState: TechTreeState = (state as any).techTreeState;
   184→    
   185→    // Select technology to sabotage
   186→    const threateningTech = getAllTech().filter(t => 
   187→      (t.category === 'alignment' || t.id.includes('detection') || t.id.includes('defensive')) &&
   188→      techTreeState.unlockedTech.includes(t.id)
   189→    );
   190→    
   191→    if (threateningTech.length === 0) {
   192→      return {
   193→        success: false,
   194→        newState: state,
   195→        effects: {},
   196→        events: [],
   197→        message: 'No threatening tech found'
   198→      };
   199→    }
   200→    
   201→    const targetTech = threateningTech[Math.floor(random() * threateningTech.length)];
   202→    
   203→    // Calculate sabotage chance based on digital capability and deception
   204→    const digitalCapability = agent.capabilityProfile.digital;
   205→    const socialCapability = agent.capabilityProfile.social; // For deception
   206→    
   207→    const sabotageChance = Math.min(0.8, 0.2 + digitalCapability * 0.15 + socialCapability * 0.1);
   208→    
   209→    // Calculate detection chance
   210→    const defensiveAIStrength = state.defensiveAI?.threatDetection?.detectSleepers || 0;
   211→    const detectionChance = Math.min(0.9, 0.3 + defensiveAIStrength * 0.4 - socialCapability * 0.1);
   212→    
   213→    const sabotageSuccess = random() < sabotageChance;
   214→    const detected = random() < detectionChance;
   215→    
   216→    if (sabotageSuccess) {
   217→      // Reduce deployment level of tech in all regions
   218→      for (const [region, deployments] of Object.entries(techTreeState.regionalDeployment)) {
   219→        const deployment = deployments.find(d => d.techId === targetTech.id);
   220→        if (deployment) {
   221→          deployment.deploymentLevel = Math.max(0, deployment.deploymentLevel - 0.15);
   222→        }
   223→      }
   224→      
   225→      if (detected) {
   226→        // Sabotage succeeded but AI was detected!
   227→        // Increase paranoia, reduce trust, potentially trigger containment
   228→        state.society.paranoia = Math.min(1, state.society.paranoia + 0.08);
   229→        
   230→        return {
   231→          success: true,
   232→          newState: state,
   233→          effects: {
   234→            techSabotage: 1,
   235→            paranoiaIncrease: 0.08,
   236→          },
   237→          events: [{
   238→            month: state.currentMonth,
   239→            type: 'sabotage',
   240→            severity: 'destructive',
