    lines.push("─────────────────────────────────────────────────────");
    lines.push("");

    availableScenarios.forEach((scenario, idx) => {
      lines.push(`[${actionNumber++}] ${scenario.name}`);
      lines.push(`    Status: ${scenario.canExecute ? '✓ EXECUTABLE' : '⏳ IN PROGRESS'}`);
