    lines.push("   Aligned AIs should deploy crisis-solving tech");
    lines.push("");
  }

  // ═══ DECISION PROMPT ═══
  lines.push("═══════════════════════════════════════════════════════");
  lines.push("CHOOSE ONE ACTION");
  lines.push("═══════════════════════════════════════════════════════");
