  minInterval: 2,  // At least 2 months between updates

  // Misaligned agents update more frequently (adversarial planning)
  agentOverrides: {
    'toxic_*': {
      fixedInterval: 3,  // Every 3 months
      eventTriggers: {
        crisisStart: true,
        extinctionPrereq: true,
      }
    }
