        "weight": 10.0,
        "condition": "while trust < 0.6",  // Conditional priority
        "duration": 3  // Focus for 3 months
      },
      {
        "action": "advance_research",
        "dimension": "digital",
        "weight": 8.0,
        "duration": 6
      },
      {
        "action": "deploy_technology",
        "tech": "fusion_power",
        "weight": 5.0,
