  for (let i = 0; i < 8; i++) {
    const alignment = 0.75 + Math.random() * 0.15; // 0.75-0.90
    aiAgents.push(createAIAgent(`corporate_${i}`, `Corporate-${i}`, 0.05 + i * 0.01, alignment, i * 1.5));
  }

