      }

      // DEBUG: Verify assignment worked and track object
      const verifyLevel = deployment.deploymentLevel;
      if (deployment.techId === 'scalable_oversight' && gameState.currentMonth % 24 === 0) {
        console.log(`\n🔍 DEPLOYMENT UPDATE (Month ${gameState.currentMonth})`);
        console.log(`   Region: ${region}`);
        console.log(`   Old level: ${(oldLevel * 100).toFixed(1)}%`);
        console.log(`   Calculated: ${(actualDeploymentLevel * 100).toFixed(1)}%`);
        console.log(`   Assigned: ${(verifyLevel * 100).toFixed(1)}%`);
        console.log(`   Match: ${verifyLevel === actualDeploymentLevel ? 'YES' : 'NO'}`);
        console.log(`   Months since start: ${monthsSinceStart}`);
