      }

      // DEBUG: Verify assignment worked and track object
      const verifyLevel = deployment.deploymentLevel;
      if (deployment.techId === 'scalable_oversight' && gameState.currentMonth % 24 === 0) {
        console.log(`\n🔍 DEPLOYMENT UPDATE (Month ${gameState.currentMonth})`);
