  return globalQueue?.getStats() || null;
}

export function resetLLMQueue() {
  if (globalQueue) {
    globalQueue.clear();
    globalQueue = null;
  }
}

export async function drainLLMQueue() {
  if (globalQueue) {
    await globalQueue.drain();
  }
}
