// Core Game Types for AI Alignment Game
// This file now imports from focused type modules and re-exports for backward compatibility

// Import all types from new focused modules
export type {
  ScenarioMode,
  ScenarioParameters,
  ConfigurationSettings,
  RNGFunction
} from './config';

export type {
  GameEvent,
  GameAction,
  AgentType
} from './events';

export type {
  ExtinctionType,
  ExtinctionMechanism,
  ExtinctionState,
  OutcomeMetrics,
  OutcomeType,
  StratifiedOutcomeType,
  MortalityBand
} from './outcomes';

export { OUTCOME_NAMES } from './outcomes';

export type {
  EconomicStage
} from './economics';

export { ECONOMIC_STAGE_NAMES } from './economics';

export type {
  TechnologyNode
} from './technology';

export type {
  AIResearchCapabilities,
  AICapabilityProfile,
  BenchmarkResult,
  AIAgent,
  EcosystemState
} from './ai-agents';

export type {
  ResearchInvestments,
  GovernmentAgent
} from './government';

export type {
  SocietySegment,
  HumanSocietyAgent
} from './society';

export type {
  GeographicPresence,
  DataCenter,
  ComputeInfrastructure,
  Organization,
  OrganizationProject
} from './organizations';

export type {
  QualityOfLifeSystems
} from './quality-of-life';

export type {
  GoldenAgeState,
  EnvironmentalAccumulation,
  SocialAccumulation,
  TechnologicalRisk,
  PsychologicalTraumaState
} from './accumulation';

export type {
  GlobalMetrics
} from './metrics';

export type {
  PositiveTippingPointsState
} from './positiveTippingPoints';

export type {
  ConsciousnessGovernanceReadiness,
  RegionalGovernance,
  ScenarioTrajectory,
  GovernanceStage,
  PoliticalRegimeType,
  PrecautionaryModel
} from './consciousness';

export interface GameState {
  // Core state  
  currentMonth: number;
  currentDay: number; // Day of the month (1-31)
  currentYear: number; // Year for leap year calculations
  daysInCurrentMonth: number; // Days in current month (28-31)

