  mean: 0.5,
  median: 0.6,
  quartiles: [0.2, 0.6, 0.8],
  violinPlotBins: [...], // For visualization
  outliers: agents.filter(a => a.trueAlignment < 0.1), // Highlight misaligned
};
```

