```typescript
import { LRUCache } from 'lru-cache';

interface CacheOptions {
  max: number;           // Max items
  ttl: number;           // Time to live (ms)
  updateAgeOnGet: boolean;
}

// In-memory cache for API responses
const cache = new LRUCache<string, any>({
  max: 500,              // Max 500 cached responses
  ttl: 1000 * 60 * 5,    // 5 minute TTL
  updateAgeOnGet: true,  // Refresh on access
});

export function getCached<T>(key: string): T | undefined {
  return cache.get(key) as T | undefined;
}

export function setCached<T>(key: string, value: T): void {
  cache.set(key, value);
}

export function invalidateCache(pattern?: string): void {
  if (!pattern) {
    cache.clear();
  } else {
    // Invalidate keys matching pattern
    const keys = Array.from(cache.keys());
    keys.filter(k => k.includes(pattern)).forEach(k => cache.delete(k));
  }
}

export function getCacheStats() {
  return {
    size: cache.size,
    max: cache.max,
    hits: cache.calculatedSize,
  };
}
```

**`src/lib/api/errors.ts`** - Error Handling
```typescript
import { NextResponse } from 'next/server';

export class ApiError extends Error {
  constructor(
    public statusCode: number,
    message: string,
    public details?: any
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

export function handleApiError(error: unknown) {
  console.error('[API Error]', error);

  if (error instanceof ApiError) {
    return NextResponse.json(
      {
        error: error.message,
        details: error.details,
        timestamp: new Date().toISOString(),
      },
      { status: error.statusCode }
    );
  }

  // Unknown error
  return NextResponse.json(
    {
      error: 'Internal Server Error',
      timestamp: new Date().toISOString(),
    },
    { status: 500 }
  );
}

export function validateRequired(params: Record<string, any>, required: string[]) {
  const missing = required.filter(key => params[key] === undefined);
  if (missing.length > 0) {
    throw new ApiError(400, `Missing required parameters: ${missing.join(', ')}`);
  }
}
```

**`src/lib/api/monitoring.ts`** - Performance Monitoring
```typescript
export class PerformanceMonitor {
  private timers: Map<string, number> = new Map();

  start(label: string): void {
    this.timers.set(label, performance.now());
  }

  end(label: string): number {
    const start = this.timers.get(label);
    if (!start) return 0;

    const duration = performance.now() - start;
    this.timers.delete(label);

    console.log(`[Performance] ${label}: ${duration.toFixed(2)}ms`);
    return duration;
  }

  measure<T>(label: string, fn: () => T): T {
    this.start(label);
    try {
      const result = fn();
      this.end(label);
      return result;
    } catch (error) {
      this.end(label);
      throw error;
    }
  }

  async measureAsync<T>(label: string, fn: () => Promise<T>): Promise<T> {
    this.start(label);
    try {
      const result = await fn();
      this.end(label);
      return result;
    } catch (error) {
      this.end(label);
      throw error;
    }
  }
}

export const monitor = new PerformanceMonitor();
```

