     1→# Subplan -1C: Overview API Endpoints
     2→
     3→**Phase:** -1 (Server-Side Aggregation API)
     4→**Agent Assignment:** Agent 3
     5→**Duration:** 2-3 days
     6→**Priority:** CRITICAL (enables Mission Control dashboard)
     7→**Dependencies:** Subplans -1A and -1B complete (needs infrastructure + aggregation)
     8→
     9→---
    10→
    11→## Context & Research
    12→
    13→**Purpose:** Create API endpoints serving pre-aggregated data for Mission Control (Overview Dashboard)
    14→
    15→### Key Documents
    16→
    17→- **Design Spec:** `docs/design/dashboard-redesign-spec.md` (Mission Control requirements)
    18→- **Architecture Review:** `reviews/dashboard_architecture_20251022.md` (Performance targets)
    19→- **Subplan -1A:** `plans/dashboard/api-infrastructure.md` (Cache, errors, types)
    20→- **Subplan -1B:** `plans/dashboard/aggregation-utilities.md` (Aggregation functions)
    21→
    22→### User Requirements
    23→
    24→**From design spec:**
    25→1. **Paradigm Cards:** 4 paradigms with scores + indicators
    26→2. **Critical Metrics:** Population, QoL, AI capabilities, alignment, crises
    27→3. **AI Agent Distribution:** 20 agents (NOT just first!)
    28→4. **Active Crises:** Crisis cards with severity/affected population
    29→5. **System Health:** 9-module grid (≤9 per tier, research-validated)
    30→
    31→**User's Requested Feature (Subplan 1A):**
    32→> "I think something that would be cool is to click on the paradigms and be able to drill down into the indicators that make up that paradigm's overall score"
    33→
    34→This subplan provides the API endpoints to enable that feature.
    35→
    36→---
    37→
    38→## Objectives
    39→
    40→Create 3 core API endpoints for Mission Control dashboard:
    41→
    42→1. **`GET /api/dashboard/overview`** - Complete mission control data
    43→2. **`GET /api/dashboard/paradigms`** - 4 paradigms + drill-down indicators
    44→3. **`GET /api/dashboard/critical-metrics`** - Population, QoL, AI, crises
    45→
    46→---
    47→
    48→## Technical Implementation
    49→
    50→### 1. Overview Endpoint
    51→
    52→**`src/app/api/dashboard/overview/route.ts`**
    53→```typescript
    54→import { NextRequest, NextResponse } from 'next/server';
    55→import { getCached, setCached } from '@/lib/api/cache';
    56→import { handleApiError, ApiError } from '@/lib/api/errors';
    57→import { monitor } from '@/lib/api/monitoring';
    58→import { ApiResponse } from '@/lib/api/types';
    59→import { getGameState } from '@/lib/gameState'; // TODO: Implement state loading
    60→import {
    61→  getPlanetaryBoundaries,
    62→  getQoLDistribution,
    63→  calculateAgentDistribution,
    64→} from '@/lib/dashboard/aggregation';
    65→
    66→export interface OverviewData {
    67→  timestamp: string;
    68→  currentMonth: number;
    69→  globalMetrics: {
    70→    population: number;
    71→    qualityOfLife: number;
    72→    aiCapabilityAvg: number;
    73→    alignmentAvg: number;
    74→  };
    75→  paradigms: {
    76→    westernLiberal: number;
    77→    development: number;
    78→    ecological: number;
    79→    indigenous: number;
    80→  };
    81→  activeCrises: Array<{
    82→    type: string;
    83→    severity: 'critical' | 'high' | 'medium' | 'low';
    84→    affectedPopulation: number;
    85→    interventionWindow: number; // months
    86→  }>;
    87→  systemHealth: {
    88→    environmental: 'green' | 'amber' | 'red';
    89→    social: 'green' | 'amber' | 'red';
    90→    technological: 'green' | 'amber' | 'red';
    91→    governmental: 'green' | 'amber' | 'red';
    92→    economic: 'green' | 'amber' | 'red';
    93→    nuclear: 'green' | 'amber' | 'red';
    94→    detection: 'green' | 'amber' | 'red';
    95→    welfare: 'green' | 'amber' | 'red';
    96→    crises: 'green' | 'amber' | 'red';
    97→  };
    98→}
    99→
   100→export async function GET(request: NextRequest) {
   101→  return monitor.measureAsync('overview-api', async () => {
   102→    try {
   103→      // Check cache
   104→      const cacheKey = 'dashboard:overview';
   105→      const cached = getCached<ApiResponse<OverviewData>>(cacheKey);
   106→      if (cached) {
   107→        return NextResponse.json(cached);
   108→      }
   109→
   110→      // Load game state (TODO: Implement state loading from simulation)
   111→      const state = await getGameState();
   112→      if (!state) {
   113→        throw new ApiError(404, 'Game state not found');
   114→      }
   115→
   116→      // Aggregate data
   117→      const aiAgents = state.aiAgents || [];
   118→      const capabilityDist = calculateAgentDistribution(
   119→        aiAgents,
   120→        agent => agent.capabilityProfile?.cognitive || 0
   121→      );
   122→      const alignmentDist = calculateAgentDistribution(
   123→        aiAgents,
   124→        agent => agent.trueAlignment || 0
   125→      );
   126→
   127→      const data: OverviewData = {
   128→        timestamp: new Date().toISOString(),
   129→        currentMonth: state.currentMonth || 0,
   130→        globalMetrics: {
   131→          population: state.globalMetrics?.population || 0,
   132→          qualityOfLife: state.globalMetrics?.qualityOfLife || 0,
   133→          aiCapabilityAvg: capabilityDist.mean,
   134→          alignmentAvg: alignmentDist.mean,
   135→        },
   136→        paradigms: {
   137→          westernLiberal:
   138→            state.multiParadigmDUI?.westernLiberal?.overallScore || 0,
   139→          development: state.multiParadigmDUI?.development?.overallScore || 0,
   140→          ecological: state.multiParadigmDUI?.ecological?.overallScore || 0,
   141→          indigenous: state.multiParadigmDUI?.indigenous?.overallScore || 0,
   142→        },
   143→        activeCrises: getActiveCrises(state),
   144→        systemHealth: getSystemHealth(state),
   145→      };
   146→
   147→      const response: ApiResponse<OverviewData> = {
   148→        data,
   149→        meta: {
   150→          timestamp: new Date().toISOString(),
   151→          cached: false,
   152→          executionTime: 0, // Will be set by monitoring
   153→        },
   154→      };
   155→
   156→      // Cache for 5 minutes
   157→      setCached(cacheKey, response);
   158→
   159→      return NextResponse.json(response);
   160→    } catch (error) {
   161→      return handleApiError(error);
   162→    }
   163→  });
   164→}
   165→
   166→function getActiveCrises(state: any): OverviewData['activeCrises'] {
   167→  const crises: OverviewData['activeCrises'] = [];
   168→
   169→  // Check planetary boundary crises
   170→  if (state.crisisSystem?.phosphorusCrisis?.active) {
   171→    crises.push({
   172→      type: 'Phosphorus Depletion',
   173→      severity: state.crisisSystem.phosphorusCrisis.severity || 'medium',
   174→      affectedPopulation:
   175→        state.crisisSystem.phosphorusCrisis.affectedPopulation || 0,
   176→      interventionWindow:
   177→        state.crisisSystem.phosphorusCrisis.interventionWindow || 0,
   178→    });
   179→  }
   180→
   181→  if (state.crisisSystem?.freshwaterCrisis?.active) {
   182→    crises.push({
   183→      type: 'Freshwater Scarcity',
   184→      severity: state.crisisSystem.freshwaterCrisis.severity || 'medium',
   185→      affectedPopulation:
   186→        state.crisisSystem.freshwaterCrisis.affectedPopulation || 0,
   187→      interventionWindow:
   188→        state.crisisSystem.freshwaterCrisis.interventionWindow || 0,
   189→    });
   190→  }
   191→
   192→  // Add more crisis checks...
   193→
   194→  return crises;
   195→}
   196→
   197→function getSystemHealth(state: any): OverviewData['systemHealth'] {
   198→  // Simplified health assessment
   199→  const boundaries = getPlanetaryBoundaries(state);
   200→  const envHealth = boundaries.some(b => b.status === 'critical')
   201→    ? 'red'
   202→    : boundaries.some(b => b.status === 'high-risk')
   203→    ? 'amber'
   204→    : 'green';
   205→
   206→  return {
   207→    environmental: envHealth,
   208→    social: 'green', // TODO: Calculate from social cohesion
   209→    technological: 'green', // TODO: Calculate from tech risk
   210→    governmental: 'green', // TODO: Calculate from government effectiveness
   211→    economic: 'green', // TODO: Calculate from economic stage
   212→    nuclear: 'green', // TODO: Calculate from nuclear risk
   213→    detection: 'green', // TODO: Calculate from detection effectiveness
   214→    welfare: 'green', // TODO: Calculate from AI welfare
   215→    crises: state.crisisSystem?.activeCrises?.length > 0 ? 'red' : 'green',
   216→  };
   217→}
