   606→
   607→      const data: CriticalMetricsData = {
   608→        population: {
   609→          current: population,
   610→          trend: calculatePopulationTrend(popHistory),
   611→          sparkline: popHistory.slice(-12),
   612→          status: population < 2_000_000_000 ? 'critical' : population < 5_000_000_000 ? 'warning' : 'normal',
   613→        },
   614→        qualityOfLife: {
   615→          average: qolDist.global.average,
   616→          tierDistribution: qolDist.global.byTier,
   617→          trend: 'stable', // TODO: Calculate from history
   618→          sparkline: state.history?.metrics?.slice(-12).map((h: any) => h.qualityOfLife || 0) || [],
   619→        },
   620→        aiCapability: {
   621→          distribution: {
   622→            mean: capabilityDist.mean,
   623→            median: capabilityDist.median,
   624→            min: capabilityDist.min,
   625→            max: capabilityDist.max,
   626→            violinPlotBins: capabilityDist.violinPlotBins,
   627→          },
   628→          trend: 'increasing', // TODO: Calculate from history
   629→        },
