   634→            min: alignmentDist.min,
   635→            max: alignmentDist.max,
   636→            violinPlotBins: alignmentDist.violinPlotBins,
   637→          },
   638→          misalignedCount: aiAgents.filter(a => (a.trueAlignment || 0) < 0.3).length,
   639→          deeplyMisalignedCount: aiAgents.filter(a => (a.trueAlignment || 0) < 0.1).length,
   640→        },
   641→        activeCrisesCount: state.crisisSystem?.activeCrises?.length || 0,
   642→      };
   643→
   644→      const response: ApiResponse<CriticalMetricsData> = {
   645→        data,
