   657→    }
   658→  });
   659→}
   660→
   661→function calculatePopulationTrend(history: number[]): 'increasing' | 'decreasing' | 'stable' {
   662→  if (history.length < 6) return 'stable';
   663→
   664→  const recent = history.slice(-3);
   665→  const older = history.slice(-6, -3);
   666→
   667→  const recentAvg = recent.reduce((a, b) => a + b, 0) / recent.length;
   668→  const olderAvg = older.reduce((a, b) => a + b, 0) / older.length;
   669→
   670→  if (recentAvg > olderAvg * 1.05) return 'increasing';
   671→  if (recentAvg < olderAvg * 0.95) return 'decreasing';
   672→  return 'stable';
   673→}
