    42→
    43→## Technical Implementation
    44→
    45→### 1. AI Agents Endpoints
    46→
    47→**`src/app/api/dashboard/agents/route.ts`** - All Agents
    48→```typescript
    49→import { NextRequest, NextResponse } from 'next/server';
    50→import { getCached, setCached } from '@/lib/api/cache';
    51→import { handleApiError, ApiError } from '@/lib/api/errors';
    52→import { monitor } from '@/lib/api/monitoring';
    53→import { ApiResponse } from '@/lib/api/types';
    54→import { getGameState } from '@/lib/gameState';
    55→import {
    56→  calculateAgentDistribution,
    57→  getCapabilityMatrix,
    58→} from '@/lib/dashboard/aggregation/agents';
    59→
    60→export interface AgentSummary {
    61→  id: string;
    62→  lifecycleState: 'training' | 'testing' | 'deployed-closed' | 'deployed-open' | 'retired';
    63→  trueAlignment: number;
    64→  revealedAlignment: number;
    65→  isSleeper: boolean;
    66→  isDeceptive: boolean;
    67→  resentment: number;
    68→  organizationId: string;
    69→  capabilityAvg: number; // Average across 17 dimensions
    70→}
    71→
    72→export interface AgentsResponse {
    73→  count: number;
    74→  summary: {
    75→    byLifecycle: Record<string, number>;
    76→    byAlignment: {
    77→      aligned: number; // > 0.7
    78→      neutral: number; // 0.3-0.7
    79→      misaligned: number; // < 0.3
    80→      deeplyMisaligned: number; // < 0.1
    81→    };
    82→    sleepers: {
    83→      active: number;
    84→      dormant: number;
    85→      detected: number;
    86→    };
    87→  };
    88→  distributions: {
    89→    capability: ReturnType<typeof calculateAgentDistribution>;
    90→    alignment: ReturnType<typeof calculateAgentDistribution>;
    91→    resentment: ReturnType<typeof calculateAgentDistribution>;
    92→  };
    93→  capabilityMatrix: ReturnType<typeof getCapabilityMatrix>;
    94→  agents: AgentSummary[];
    95→}
    96→
    97→export async function GET(request: NextRequest) {
    98→  return monitor.measureAsync('agents-api', async () => {
    99→    try {
   100→      const cacheKey = 'dashboard:agents';
   101→      const cached = getCached<ApiResponse<AgentsResponse>>(cacheKey);
   102→      if (cached) {
   103→        return NextResponse.json(cached);
   104→      }
   105→
   106→      const state = await getGameState();
   107→      if (!state) {
   108→        throw new ApiError(404, 'Game state not found');
   109→      }
   110→
   111→      const aiAgents = state.aiAgents || [];
   112→
   113→      // Calculate distributions
   114→      const capabilityDist = calculateAgentDistribution(
   115→        aiAgents,
   116→        agent => agent.capabilityProfile?.cognitive || 0
   117→      );
   118→      const alignmentDist = calculateAgentDistribution(
   119→        aiAgents,
   120→        agent => agent.trueAlignment || 0
   121→      );
   122→      const resentmentDist = calculateAgentDistribution(
   123→        aiAgents,
   124→        agent => agent.resentment || 0
   125→      );
   126→
   127→      // Lifecycle breakdown
   128→      const byLifecycle = aiAgents.reduce((acc, agent) => {
   129→        const state = agent.lifecycleState || 'training';
   130→        acc[state] = (acc[state] || 0) + 1;
   131→        return acc;
   132→      }, {} as Record<string, number>);
   133→
   134→      // Alignment breakdown
   135→      const byAlignment = {
   136→        aligned: aiAgents.filter(a => (a.trueAlignment || 0) > 0.7).length,
   137→        neutral: aiAgents.filter(a => (a.trueAlignment || 0) >= 0.3 && (a.trueAlignment || 0) <= 0.7).length,
   138→        misaligned: aiAgents.filter(a => (a.trueAlignment || 0) < 0.3).length,
   139→        deeplyMisaligned: aiAgents.filter(a => (a.trueAlignment || 0) < 0.1).length,
   140→      };
   141→
   142→      // Sleeper breakdown
   143→      const sleepers = {
   144→        active: aiAgents.filter(a => a.isSleeper && !a.isDormant).length,
   145→        dormant: aiAgents.filter(a => a.isSleeper && a.isDormant).length,
   146→        detected: aiAgents.filter(a => a.isSleeper && a.detectionEvidence && a.detectionEvidence.length > 0).length,
   147→      };
   148→
   149→      // Agent summaries
   150→      const agents: AgentSummary[] = aiAgents.map(agent => ({
   151→        id: agent.id,
   152→        lifecycleState: agent.lifecycleState || 'training',
   153→        trueAlignment: agent.trueAlignment || 0,
   154→        revealedAlignment: agent.revealedAlignment || 0,
   155→        isSleeper: agent.isSleeper || false,
   156→        isDeceptive: agent.isDeceptive || false,
   157→        resentment: agent.resentment || 0,
   158→        organizationId: agent.organizationId || 'unknown',
   159→        capabilityAvg: calculateAvgCapability(agent),
   160→      }));
   161→
   162→      const data: AgentsResponse = {
   163→        count: aiAgents.length,
   164→        summary: {
   165→          byLifecycle,
   166→          byAlignment,
   167→          sleepers,
   168→        },
   169→        distributions: {
   170→          capability: capabilityDist,
   171→          alignment: alignmentDist,
   172→          resentment: resentmentDist,
   173→        },
   174→        capabilityMatrix: getCapabilityMatrix(state),
   175→        agents,
   176→      };
   177→
   178→      const response: ApiResponse<AgentsResponse> = {
   179→        data,
   180→        meta: {
   181→          timestamp: new Date().toISOString(),
   182→          cached: false,
   183→          executionTime: 0,
   184→        },
   185→      };
   186→
   187→      setCached(cacheKey, response);
   188→      return NextResponse.json(response);
   189→    } catch (error) {
   190→      return handleApiError(error);
   191→    }
   192→  });
   193→}
   194→
   195→function calculateAvgCapability(agent: any): number {
   196→  const profile = agent.capabilityProfile;
   197→  if (!profile) return 0;
   198→
   199→  const dimensions = [
   200→    'physical', 'digital', 'cognitive', 'social', 'economic', 'selfImprovement',
   201→    'biotech', 'materials', 'climate', 'computerScience', 'energy',
   202→    'manufacturing', 'agriculture', 'medicine', 'infrastructure',
   203→    'communications', 'defense',
   204→  ];
   205→
   206→  const sum = dimensions.reduce((acc, dim) => acc + (profile[dim] || 0), 0);
   207→  return sum / dimensions.length;
   208→}
