     8→
     9→---
    10→
    11→## Context & Research
    12→
    13→**Problem:** GameState is 900+ lines with 40+ systems, can't load all in browser
    14→**Solution:** Aggregation functions that reduce data to essential summaries
    15→
    16→### Key Documents
    17→
    18→- **GameState Structure:** `src/types/game.ts` (900+ lines, 40+ systems)
    19→- **Architecture Review:** `reviews/dashboard_architecture_20251022.md` (CRITICAL Issue #1)
    20→- **Design Spec:** `docs/design/dashboard-redesign-spec.md` (Data requirements)
    21→- **Research:** `research/dashboard_visualization_best_practices_20251022.md` (Aggregation fallacy)
    22→
    23→### Research Insight: Aggregation Fallacy
    24→
    25→**From Railsback & Grimm (2019):**
    26→> "Aggregating agent-based model outputs obscures bimodal distributions, outliers, and heterogeneity critical to understanding system dynamics."
    27→
    28→**Implication:** We must provide BOTH aggregates AND distributions (violin plots, histograms)
    29→
    30→**Example:**
    31→```typescript
    32→// ❌ BAD - Hides bimodal distribution
    33→const avgAlignment = mean(agents.map(a => a.trueAlignment)); // 0.5 (meaningless!)
    34→
    35→// ✅ GOOD - Shows distribution
    36→const alignmentDist = {
    37→  mean: 0.5,
    38→  median: 0.6,
    39→  quartiles: [0.2, 0.6, 0.8],
    40→  violinPlotBins: [...], // For visualization
    41→  outliers: agents.filter(a => a.trueAlignment < 0.1), // Highlight misaligned
    42→};
    43→```
    44→
    45→---
    46→
    47→## Objectives
    48→
    49→Create aggregation functions that transform full GameState into dashboard-ready summaries:
    50→
    51→1. **Time Windowing:** Extract last N months of data
    52→2. **Regional Aggregation:** Roll up 15 countries into summaries
    53→3. **Agent Distribution:** Convert 20 agents into violin plot data
    54→4. **Planetary Boundaries:** Aggregate 9 boundaries with thresholds
    55→5. **Quality of Life:** 17-dimensional × 5-tier distribution
    56→6. **Crisis Systems:** Active crises with severity/affected population
    57→
    58→---
    59→
    60→## Technical Implementation
    61→
    62→### Directory Structure
    63→
    64→```
    65→src/lib/dashboard/
    66→├── aggregation/
    67→│   ├── time.ts              # Time windowing utilities
    68→│   ├── regional.ts          # Regional aggregation
    69→│   ├── agents.ts            # AI agent distribution
    70→│   ├── environment.ts       # Planetary boundaries
    71→│   ├── qualityOfLife.ts     # QoL distribution
    72→│   ├── government.ts        # Government systems
    73→│   ├── crises.ts            # Crisis systems
    74→│   ├── technology.ts        # Tech tree
    75→│   └── index.ts             # Re-exports
    76→└── types.ts                 # Aggregated data types
    77→```
    78→
    79→### 1. Time Windowing Utilities
    80→
    81→**`src/lib/dashboard/aggregation/time.ts`**
    82→```typescript
    83→import { GameState } from '@/types/game';
    84→
    85→export interface TimeWindow {
    86→  startMonth: number;
    87→  endMonth: number;
    88→  months: number[];
    89→}
    90→
    91→/**
    92→ * Get last N months of data
    93→ */
    94→export function getTimeWindow(
    95→  state: GameState,
    96→  range: number = 12
    97→): TimeWindow {
    98→  const currentMonth = state.currentMonth;
    99→  const startMonth = Math.max(0, currentMonth - range);
   100→  const months = Array.from(
   101→    { length: currentMonth - startMonth + 1 },
   102→    (_, i) => startMonth + i
   103→  );
   104→
   105→  return { startMonth, endMonth: currentMonth, months };
   106→}
   107→
   108→/**
   109→ * Extract time series data for a metric
   110→ */
   111→export function extractTimeSeries<T>(
   112→  history: T[],
   113→  window: TimeWindow
   114→): T[] {
   115→  return history.slice(window.startMonth, window.endMonth + 1);
   116→}
   117→
   118→/**
   119→ * Calculate trend (increasing, decreasing, stable)
   120→ */
   121→export function calculateTrend(
   122→  values: number[],
   123→  threshold: number = 0.05
   124→): 'increasing' | 'decreasing' | 'stable' {
   125→  if (values.length < 2) return 'stable';
   126→
   127→  const recent = values.slice(-6); // Last 6 months
   128→  const older = values.slice(-12, -6); // Previous 6 months
   129→
   130→  const recentAvg = recent.reduce((a, b) => a + b, 0) / recent.length;
   131→  const olderAvg = older.reduce((a, b) => a + b, 0) / (older.length || 1);
   132→
   133→  const change = (recentAvg - olderAvg) / (olderAvg || 1);
   134→
   135→  if (change > threshold) return 'increasing';
   136→  if (change < -threshold) return 'decreasing';
   137→  return 'stable';
   138→}
   139→
   140→/**
   141→ * Get sparkline data (simplified for rendering)
   142→ */
   143→export function getSparklineData(
   144→  values: number[],
   145→  maxPoints: number = 12
   146→): number[] {
   147→  if (values.length <= maxPoints) return values;
   148→
   149→  // Downsample to maxPoints
   150→  const step = values.length / maxPoints;
   151→  return Array.from({ length: maxPoints }, (_, i) =>
   152→    values[Math.floor(i * step)]
   153→  );
   154→}
   155→```
   156→
   157→### 2. Regional Aggregation
   158→
   159→**`src/lib/dashboard/aggregation/regional.ts`**
   160→```typescript
   161→import { GameState, CountryPopulationData } from '@/types/game';
   162→
   163→export interface RegionalSummary {
   164→  total: number;
   165→  byCountry: Record<string, number>;
   166→  topCountries: Array<{ country: string; value: number }>;
   167→  bottomCountries: Array<{ country: string; value: number }>;
   168→}
   169→
   170→/**
   171→ * Aggregate metric across 15 regions
   172→ */
   173→export function aggregateRegional(
   174→  state: GameState,
   175→  metric: (country: CountryPopulationData) => number
   176→): RegionalSummary {
   177→  const countries = state.countryPopulationSystem?.countries || [];
   178→
   179→  const byCountry: Record<string, number> = {};
   180→  let total = 0;
   181→
   182→  for (const country of countries) {
   183→    const value = metric(country);
   184→    byCountry[country.name] = value;
   185→    total += value;
   186→  }
   187→
   188→  // Sort for top/bottom
   189→  const sorted = Object.entries(byCountry)
   190→    .map(([country, value]) => ({ country, value }))
   191→    .sort((a, b) => b.value - a.value);
   192→
   193→  return {
   194→    total,
   195→    byCountry,
   196→    topCountries: sorted.slice(0, 5),
   197→    bottomCountries: sorted.slice(-5).reverse(),
   198→  };
   199→}
   200→
