import { NextRequest, NextResponse } from 'next/server';
import { getCached, setCached } from '@/lib/api/cache';
import { handleApiError, ApiError } from '@/lib/api/errors';
import { monitor } from '@/lib/api/monitoring';
import { ApiResponse } from '@/lib/api/types';
import { getGameState } from '@/lib/gameState';

export interface CrisisData {
  type: string;
  active: boolean;
  severity: 'critical' | 'high' | 'medium' | 'low';
  affectedPopulation: number;
  interventionWindow: number; // months
  cascadeMultiplier: number;
  regionalImpact: Record<string, number>;
}

export interface CrisesResponse {
  activeCrises: CrisisData[];
  cascadePotential: number;
  totalAffectedPopulation: number;
}

export async function GET(request: NextRequest) {
  return monitor.measureAsync('crises-api', async () => {
    try {
      const cacheKey = 'dashboard:crises';
      const cached = getCached<ApiResponse<CrisesResponse>>(cacheKey);
      if (cached) {
        return NextResponse.json(cached);
      }

      const state = await getGameState();
      if (!state) {
        throw new ApiError(404, 'Game state not found');
      }

      const crises: CrisisData[] = [];

      // Extract active crises from state
      if (state.crisisSystem?.phosphorusCrisis?.active) {
        crises.push({
          type: 'Phosphorus Depletion',
          active: true,
          severity: state.crisisSystem.phosphorusCrisis.severity || 'medium',
          affectedPopulation:
            state.crisisSystem.phosphorusCrisis.affectedPopulation || 0,
          interventionWindow:
            state.crisisSystem.phosphorusCrisis.interventionWindow || 0,
          cascadeMultiplier:
            state.crisisSystem.phosphorusCrisis.cascadeMultiplier || 1.0,
          regionalImpact: state.crisisSystem.phosphorusCrisis.regionalImpact || {},
        });
      }

      if (state.crisisSystem?.freshwaterCrisis?.active) {
        crises.push({
          type: 'Freshwater Scarcity',
          active: true,
          severity: state.crisisSystem.freshwaterCrisis.severity || 'medium',
          affectedPopulation:
            state.crisisSystem.freshwaterCrisis.affectedPopulation || 0,
          interventionWindow:
            state.crisisSystem.freshwaterCrisis.interventionWindow || 0,
          cascadeMultiplier:
            state.crisisSystem.freshwaterCrisis.cascadeMultiplier || 1.0,
          regionalImpact: state.crisisSystem.freshwaterCrisis.regionalImpact || {},
        });
      }

      if (state.crisisSystem?.oceanAcidificationCrisis?.active) {
        crises.push({
          type: 'Ocean Acidification',
          active: true,
          severity: state.crisisSystem.oceanAcidificationCrisis.severity || 'medium',
          affectedPopulation:
            state.crisisSystem.oceanAcidificationCrisis.affectedPopulation || 0,
          interventionWindow:
            state.crisisSystem.oceanAcidificationCrisis.interventionWindow || 0,
          cascadeMultiplier:
            state.crisisSystem.oceanAcidificationCrisis.cascadeMultiplier || 1.0,
          regionalImpact: state.crisisSystem.oceanAcidificationCrisis.regionalImpact || {},
        });
      }

      if (state.crisisSystem?.novelEntitiesCrisis?.active) {
        crises.push({
          type: 'Novel Entities (PFAS)',
          active: true,
          severity: state.crisisSystem.novelEntitiesCrisis.severity || 'medium',
          affectedPopulation:
            state.crisisSystem.novelEntitiesCrisis.affectedPopulation || 0,
          interventionWindow:
            state.crisisSystem.novelEntitiesCrisis.interventionWindow || 0,
          cascadeMultiplier:
            state.crisisSystem.novelEntitiesCrisis.cascadeMultiplier || 1.0,
          regionalImpact: state.crisisSystem.novelEntitiesCrisis.regionalImpact || {},
        });
      }

      if (state.crisisSystem?.nuclearCrisis?.active) {
        crises.push({
          type: 'Nuclear Crisis',
          active: true,
          severity: state.crisisSystem.nuclearCrisis.severity || 'critical',
          affectedPopulation:
            state.crisisSystem.nuclearCrisis.affectedPopulation || 0,
          interventionWindow:
            state.crisisSystem.nuclearCrisis.interventionWindow || 0,
          cascadeMultiplier:
            state.crisisSystem.nuclearCrisis.cascadeMultiplier || 1.0,
          regionalImpact: state.crisisSystem.nuclearCrisis.regionalImpact || {},
        });
      }

      const totalAffectedPopulation = crises.reduce(
        (sum, c) => sum + c.affectedPopulation,
        0
      );

      const data: CrisesResponse = {
        activeCrises: crises,
        cascadePotential: state.crisisSystem?.cascadePotential || 0,
        totalAffectedPopulation,
      };

      const response: ApiResponse<CrisesResponse> = {
        data,
        meta: {
          timestamp: new Date().toISOString(),
          cached: false,
          executionTime: 0,
        },
      };

      setCached(cacheKey, response);
      return NextResponse.json(response);
    } catch (error) {
      return handleApiError(error);
    }
  });
}

