   222→### 3. AI Agent Distribution
   223→
   224→**`src/lib/dashboard/aggregation/agents.ts`**
   225→```typescript
   226→import { GameState, AIAgent } from '@/types/game';
   227→
   228→export interface AgentDistribution {
   229→  count: number;
   230→  mean: number;
   231→  median: number;
   232→  quartiles: [number, number, number]; // Q1, Q2, Q3
   233→  min: number;
   234→  max: number;
   235→  violinPlotBins: Array<{ value: number; count: number }>;
   236→  outliers: AIAgent[];
   237→}
   238→
   239→/**
   240→ * Calculate distribution statistics for agent metric
   241→ */
   242→export function calculateAgentDistribution(
   243→  agents: AIAgent[],
   244→  metric: (agent: AIAgent) => number,
   245→  outlierThreshold: number = 2 // Standard deviations
   246→): AgentDistribution {
   247→  if (agents.length === 0) {
   248→    return {
   249→      count: 0,
   250→      mean: 0,
   251→      median: 0,
   252→      quartiles: [0, 0, 0],
   253→      min: 0,
   254→      max: 0,
   255→      violinPlotBins: [],
   256→      outliers: [],
   257→    };
   258→  }
   259→
   260→  const values = agents.map(metric).sort((a, b) => a - b);
   261→  const count = values.length;
   262→
   263→  // Calculate statistics
   264→  const mean = values.reduce((a, b) => a + b, 0) / count;
   265→  const median = values[Math.floor(count / 2)];
   266→  const q1 = values[Math.floor(count * 0.25)];
   267→  const q3 = values[Math.floor(count * 0.75)];
   268→  const min = values[0];
   269→  const max = values[values.length - 1];
   270→
   271→  // Violin plot bins (20 bins)
   272→  const binCount = 20;
   273→  const binSize = (max - min) / binCount;
   274→  const violinPlotBins = Array.from({ length: binCount }, (_, i) => {
   275→    const binMin = min + i * binSize;
   276→    const binMax = binMin + binSize;
   277→    const count = values.filter(v => v >= binMin && v < binMax).length;
   278→    return { value: binMin + binSize / 2, count };
   279→  });
   280→
   281→  // Detect outliers (beyond 2 standard deviations)
   282→  const stdDev = Math.sqrt(
   283→    values.reduce((sum, v) => sum + Math.pow(v - mean, 2), 0) / count
   284→  );
   285→  const outliers = agents.filter(agent => {
   286→    const value = metric(agent);
   287→    return Math.abs(value - mean) > outlierThreshold * stdDev;
   288→  });
   289→
   290→  return {
   291→    count,
   292→    mean,
   293→    median,
   294→    quartiles: [q1, median, q3],
   295→    min,
   296→    max,
   297→    violinPlotBins,
   298→    outliers,
   299→  };
   300→}
