   356→```typescript
   357→import { GameState, PlanetaryBoundaryName } from '@/types/game';
   358→
   359→export interface PlanetaryBoundaryData {
   360→  name: PlanetaryBoundaryName;
   361→  current: number;
   362→  threshold: number;
   363→  safeZone: number;
   364→  status: 'safe' | 'increasing-risk' | 'high-risk' | 'critical';
   365→  trend: 'improving' | 'worsening' | 'stable';
   366→  regionalVariation?: Record<string, number>;
   367→}
   368→
   369→export function getPlanetaryBoundaries(
   370→  state: GameState
   371→): PlanetaryBoundaryData[] {
   372→  const boundaries = state.planetaryBoundaries;
   373→  if (!boundaries) return [];
   374→
   375→  const boundaryNames: PlanetaryBoundaryName[] = [
   376→    'climateChange',
   377→    'biosphereIntegrity',
   378→    'landSystemChange',
   379→    'freshwaterUse',
   380→    'biogeochemicalFlows',
   381→    'oceanAcidification',
   382→    'atmosphericAerosol',
   383→    'stratosphericOzone',
   384→    'novelEntities',
   385→  ];
   386→
   387→  return boundaryNames.map(name => {
   388→    const current = (boundaries as any)[name] || 0;
   389→    const threshold = 1.0; // Normalized threshold
   390→    const safeZone = 0.7; // Safe operating space
   391→
   392→    let status: PlanetaryBoundaryData['status'] = 'safe';
   393→    if (current >= threshold) status = 'critical';
   394→    else if (current >= 0.9) status = 'high-risk';
   395→    else if (current >= safeZone) status = 'increasing-risk';
   396→
   397→    // Calculate trend from history
   398→    const history = state.history?.planetaryBoundaries || [];
   399→    const recentValues = history.slice(-6).map(h => (h as any)?.[name] || 0);
   400→    const trend =
   401→      recentValues.length >= 2 &&
   402→      recentValues[recentValues.length - 1] <
   403→        recentValues[recentValues.length - 2]
   404→        ? 'improving'
   405→        : recentValues.length >= 2 &&
   406→          recentValues[recentValues.length - 1] >
   407→            recentValues[recentValues.length - 2]
   408→        ? 'worsening'
   409→        : 'stable';
   410→
   411→    return {
   412→      name,
   413→      current,
   414→      threshold,
   415→      safeZone,
   416→      status,
   417→      trend,
   418→    };
   419→  });
   420→}
